    if (strlen(var_name) >= MAX_ENV_VAR_NAME_LEN || strlen(var_value) >= MAX_ENV_VAR_VALUE_LEN) {
        return -1; // 长度超出限制
    }

    // 检查是否达到最大环境变量数量限制
    if (env_var_count >= MAX_ENV_VARS) {
        return -1; // 达到最大环境变量数量限制
    }

    // 构建环境变量字符串 (name=value)
    char* env_str = env_vars[env_var_count];
    size_t name_len = strlen(var_name);
    size_t value_len = strlen(var_value);

